package com.englishhero.reading.writing;
import com.englishhero.identity.*;
import com.englishhero.reading.*;
import com.englishhero.web.BusinessException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
import static com.englishhero.reading.writing.WritingDtos.*;
@Service
public class PersonalWritingService {
 private final PersonalWritingMapper personal;private final WritingMapper materials;private final ReadingService reading;private final ArticleMapper articles;private final ReadingMapper progress;private final IdentityService identities;private final ObjectMapper json;
 public PersonalWritingService(PersonalWritingMapper personal,WritingMapper materials,ReadingService reading,ArticleMapper articles,ReadingMapper progress,IdentityService identities,ObjectMapper json){this.personal=personal;this.materials=materials;this.reading=reading;this.articles=articles;this.progress=progress;this.identities=identities;this.json=json;}
 @Transactional(readOnly=true)public Personal detail(SessionPrincipal actor,String id){identities.current(actor);return detail(actor,row(id,false),false);}
 @Transactional(readOnly=true)public java.util.Map<String,Boolean> states(SessionPrincipal actor,String article,String version){reading.version(actor,article,version);return personal.states(actor.userId(),ArticleRules.id(article,"articleId"),ArticleRules.id(version,"versionId"));}
 @Transactional(readOnly=true)public ReadingDtos.PageDto<Personal> list(SessionPrincipal actor,String view,int page,int size){identities.current(actor);if(!java.util.Set.of("favorites","imitations").contains(view))throw BusinessException.invalid("view","请选择收藏或仿写");ArticleRules.page(page);ArticleRules.pageSize(size);var items=personal.ids(actor.userId(),view,page,size).stream().map(id->detail(actor,row(""+id,false),false)).toList();return new ReadingDtos.PageDto<>(items,page,size,personal.count(actor.userId(),view));}
 @Transactional public Personal favorite(SessionPrincipal actor,String id,FavoriteInput input){identities.current(actor);personal.lockUser(actor.userId());var row=row(id,true);if(!availableCurrent(actor,row))throw unavailable();if(input==null||input.materialRevision()==null||input.materialRevision()!=row.revision())throw new BusinessException(409,"WRITING_CHANGED","素材已更新，请重新加载后确认");var existing=personal.favorite(actor.userId(),row.id(),true);if(existing==null||!existing.active())personal.favorite(actor.userId(),row.id(),row.published());return detail(actor,row,true);}
 @Transactional public void cancel(SessionPrincipal actor,String id){identities.current(actor);personal.lockUser(actor.userId());var row=row(id,true);var existing=personal.favorite(actor.userId(),row.id(),true);if(existing==null&&!availableCurrent(actor,row))throw missing();personal.cancel(actor.userId(),row.id());}
 @Transactional public Personal save(SessionPrincipal actor,String id,ImitationInput input){identities.current(actor);personal.lockUser(actor.userId());var row=row(id,true);if(!availableCurrent(actor,row))throw unavailable();if(input==null)throw BusinessException.invalid("text","请填写英文仿写");String text=ArticleContent.text(input.text(),"text",2000,true);if(!text.matches("(?s).*[A-Za-z].*"))throw BusinessException.invalid("text","请写一句包含英文的句子");var previous=personal.imitation(actor.userId(),row.id(),true);int lock=previous==null?0:previous.lockVersion(),revision=previous==null?row.revision():previous.materialRevision();if(input.expectedLockVersion()==null||input.expectedLockVersion()!=lock)throw new BusinessException(409,"IMITATION_CONFLICT","仿写已在其他页面更新，请先查看最新内容");if(input.materialRevision()==null||input.materialRevision()!=revision)throw new BusinessException(409,"WRITING_CHANGED","参考素材已变化，请重新加载后确认");personal.save(actor.userId(),row.id(),text,revision,row.published(),previous!=null);return detail(actor,row,true);}
 private Personal detail(SessionPrincipal actor,WritingMapper.Row row,boolean lock){var favorite=personal.favorite(actor.userId(),row.id(),lock);var own=personal.imitation(actor.userId(),row.id(),lock);boolean available=lock?availableCurrent(actor,row):available(actor,row);if(!available&&(favorite==null||!favorite.active())&&own==null)throw missing();Content snapshot=own!=null?decode(own.snapshot()):favorite!=null?decode(favorite.snapshot()):null;var imitation=own==null?null:new SavedImitation(own.text(),own.materialRevision(),decode(own.snapshot()),own.lockVersion());var material=available?new PublishedMaterial(""+row.id(),""+row.articleId(),""+row.versionId(),decode(row.published()),row.revision()):null;return new Personal(""+row.id(),""+row.articleId(),""+row.versionId(),available?decode(row.published()).expression():snapshot.expression(),available,favorite!=null&&favorite.active(),material,imitation);}
 private WritingMapper.Row row(String id,boolean lock){var row=materials.get(ArticleRules.id(id,"materialId"),lock);if(row==null)throw missing();return row;}
 private boolean available(SessionPrincipal actor,WritingMapper.Row row){if(!row.status().equals("PUBLISHED"))return false;try{reading.version(actor,""+row.articleId(),""+row.versionId());return true;}catch(BusinessException e){if(e.status==404)return false;throw e;}}
 private boolean availableCurrent(SessionPrincipal actor,WritingMapper.Row row){if(!row.status().equals("PUBLISHED"))return false;var article=articles.article(row.articleId(),true);if(article==null||article.status().equals("DRAFT"))return false;return (article.status().equals("PUBLISHED")&&java.util.Objects.equals(article.publishedVersionId(),row.versionId()))||progress.progressCurrent(actor.userId(),row.versionId())!=null;}
 private Content decode(String s){return json.readValue(s,Content.class);}
 private BusinessException missing(){return new BusinessException(404,"WRITING_NOT_FOUND","素材不存在或暂不可访问");}
 private BusinessException unavailable(){return new BusinessException(409,"WRITING_UNAVAILABLE","素材已下架或暂不可访问，已有个人记录保留");}
}
